// fmaScriptHashes is generated by tools/fma-script-hashes. It lists the sha256 of
// every install and uninstall script Fleet has published for a maintained app,
// keyed by slug, so the backfill below can tell a Fleet-generated script apart
// from one an admin replaced.
//
//go:embed data/fma_script_hashes.txt
var fmaScriptHashes string

func init() {
	MigrationClient.AddMigration(Up_20260824183354, Down_20260824183354)
}

func Up_20260824183354(tx *sql.Tx) error {
	return withSteps([]migrationStep{
		addScriptEditedColumns,
		incrementalMigrationStep(countMaintainedAppInstallers, backfillScriptEditedFlags),
	}, tx)
}

func addScriptEditedColumns(tx *sql.Tx) error {
	if columnExists(tx, "software_installers", "install_script_edited") {
		return nil
	}
	if _, err := tx.Exec(`
		ALTER TABLE software_installers
		ADD COLUMN install_script_edited TINYINT(1) NOT NULL DEFAULT 0,
		ADD COLUMN uninstall_script_edited TINYINT(1) NOT NULL DEFAULT 0,
		ALGORITHM=INSTANT
	`); err != nil {
		return fmt.Errorf("adding script edited columns to software_installers: %w", err)
	}
	return nil
}

func countMaintainedAppInstallers(tx *sql.Tx) (uint64, error) {
	var total uint64
	err := tx.QueryRow(`
		SELECT COUNT(*)
		FROM software_installers si
		JOIN fleet_maintained_apps fma ON fma.id = si.fleet_maintained_app_id`).Scan(&total)
	return total, err
}

// installerScriptHashes is one Fleet-maintained app installer with its scripts
// hashed by MySQL, so the script bodies never cross the wire.
type installerScriptHashes struct {
	ID             uint   `db:"id"`
	Slug           string `db:"slug"`
	Install        string `db:"install"`
	Uninstall      string `db:"uninstall"`
	UpdatedAfterTo bool   `db:"updated_after_to"`
}

// backfillScriptEditedFlags marks the Fleet-maintained app installers whose
// scripts Fleet did not publish, so the auto-update cron keeps carrying them
// forward. Anything Fleet published, and anything the generated corpus can't
// speak to because the row changed after the corpus was cut, keeps the column
// default of 0 and follows the manifest from here on.
func backfillScriptEditedFlags(tx *sql.Tx, increment incrementCountFn) error {
	install, uninstall, toDate, err := parseFMAScriptHashes(fmaScriptHashes)
	if err != nil {
		return err
	}

	txx := sqlx.Tx{Tx: tx, Mapper: reflectx.NewMapperFunc("db", sqlx.NameMapper)}

	const batchSize = 100
	var lastID uint
	for {
		var rows []installerScriptHashes
		if err := txx.Select(&rows, `
			SELECT
				si.id,
				fma.slug,
				-- the installer filename is substituted the same way the generated
				-- hashes were, so a script that only changed because the version
				-- bumped still matches
				SHA2(REPLACE(REPLACE(sci.contents,
					CONCAT('"$TMPDIR/', si.filename, '"'),  '"$TMPDIR/__FLEET_INSTALLER_FILE__"'),
					CONCAT('"$TMPDIR"/', si.filename, ' '), '"$TMPDIR"/__FLEET_INSTALLER_FILE__ '), 256) AS install,
				SHA2(scu.contents, 256) AS uninstall,
				si.updated_at > ? AS updated_after_to
				-- an hour of timezone skew here doesn't matter: the cutoff is days or
				-- weeks before any instance runs this
			FROM software_installers si FORCE INDEX (PRIMARY)
			JOIN fleet_maintained_apps fma ON fma.id = si.fleet_maintained_app_id
			JOIN script_contents sci ON sci.id = si.install_script_content_id
			JOIN script_contents scu ON scu.id = si.uninstall_script_content_id
			WHERE si.id > ?
			ORDER BY si.id
			LIMIT ?`, toDate.UTC(), lastID, batchSize); err != nil {
			return fmt.Errorf("selecting fleet-maintained app installers after id %d: %w", lastID, err)
		}
		if len(rows) == 0 {
			return nil
		}

		var editedInstall, editedUninstall []uint
		for _, row := range rows {
			increment()
			if row.UpdatedAfterTo {
				continue
			}
			if !install.has(row.Slug, row.Install) {
				editedInstall = append(editedInstall, row.ID)
			}
			if !uninstall.has(row.Slug, row.Uninstall) {
				editedUninstall = append(editedUninstall, row.ID)
			}
		}

		if err := markScriptEdited(txx, "install_script_edited", editedInstall); err != nil {
			return err
		}
		if err := markScriptEdited(txx, "uninstall_script_edited", editedUninstall); err != nil {
			return err
		}

		lastID = rows[len(rows)-1].ID
	}
}

func markScriptEdited(txx sqlx.Tx, column string, ids []uint) error {
	if len(ids) == 0 {
		return nil
	}
	query, args, err := sqlx.In(
		fmt.Sprintf(`UPDATE software_installers SET %s = 1 WHERE id IN (?)`, column), ids)
	if err != nil {
		return fmt.Errorf("building %s update: %w", column, err)
	}
	if _, err := txx.Exec(query, args...); err != nil {
		return fmt.Errorf("marking %s on %d installers: %w", column, len(ids), err)
	}
	return nil
}

// scriptHashSet holds "<slug> <sha256>" keys. Scripts are shared between apps, so
// the slug is part of the key, not just the hash.
type scriptHashSet map[string]struct{}

func (s scriptHashSet) has(slug string, hash string) bool {
	_, ok := s[slug+" "+hash]
	return ok
}

// parseFMAScriptHashes reads the generated corpus. Its header carries the commit
// the corpus was cut at and that commit's date, which bounds which installers the
// corpus can speak to. The date is compared against a TIMESTAMP column, so it is
// parsed here rather than handed to MySQL as an RFC 3339 string.
func parseFMAScriptHashes(contents string) (install scriptHashSet, uninstall scriptHashSet, toDate time.Time, err error) {
	install, uninstall = scriptHashSet{}, scriptHashSet{}

	for line := range strings.SplitSeq(contents, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			continue
		}
		switch {
		case fields[0] == "#" && len(fields) == 4 && fields[1] == "to":
			toDate, err = time.Parse(time.RFC3339, fields[3])
			if err != nil {
				return nil, nil, time.Time{}, fmt.Errorf("parsing fma script hashes cutoff %q: %w", fields[3], err)
			}
		case fields[0] == "#":
		case fields[0] == "i" && len(fields) == 3:
			install[fields[1]+" "+fields[2]] = struct{}{}
		case fields[0] == "u" && len(fields) == 3:
			uninstall[fields[1]+" "+fields[2]] = struct{}{}
		default:
			return nil, nil, time.Time{}, fmt.Errorf("unexpected line in fma script hashes: %q", line)
		}
	}

	if toDate.IsZero() {
		return nil, nil, time.Time{}, fmt.Errorf("fma script hashes is missing its \"# to <commit> <date>\" header")
	}
	return install, uninstall, toDate, nil
}

